import logging

logger = logging.getLogger(__name__)


class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self.stock = stock

    def place_order(
        self, user: str, item: str, quantity: int, is_admin: bool = False
    ) -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            reservation_id = self.stock.reserve(item, quantity)
            return (
                200,
                f"Order placed successfully for {user}. Reservation ID: {reservation_id}.",
            )
        except Exception as exc:
            # Log the unexpected error with full traceback
            logger.error("Failed to place order for user %s: %s", user, exc, exc_info=True)

            if is_admin:
                message = f"An unexpected error occurred: {type(exc).__name__}: {exc}"
            else:
                message = "An unexpected error occurred. Please try again later."

            return (500, message)
